function information(title,body){openModal('info',{title,body});}
function outputScene(){return JSON.stringify({selection:state.selection,marks:state.marks});}
function simulateAutoCopy(){const scene=outputScene();if(state.autoSaveReceipt?.scene!==scene){state.autoSaveReceipt={scene,path:filenamePreview()};state.autoSaveWrites=(state.autoSaveWrites||0)+1;}}
function cancelCapture(){if(state.guideCapture){state.guideCapture=false;navigate('onboarding/practice',true);return;}const editing=state.editingPin;state.editingPin=false;if(editing)state.pinHidden=false;state.selection=null;resetEdits();navigate(editing?'pins':'idle',true);}
function prototypeCaptureLayout(){return JSON.stringify([innerWidth,innerHeight,devicePixelRatio]);}
function repeatCapture(){
 const previous=state.lastRegion;goCapture();
 if(!saved.rememberRegion)state.repeatNotice='区域记忆已关闭，请手动框选。';
 else if(!previous)state.repeatNotice='本次运行尚无成功截图，请手动框选。';
 else if(previous.layout!==prototypeCaptureLayout())state.repeatNotice='显示器布局或 DPI 已变化，请重新框选。';
 else {state.selection=clone(previous.region);state.repeatNotice='已恢复上次区域；重新采集画面，不带入旧标注。';}
 render();
}
function completionFeedback(message){state.lastCompletion={mode:saved.afterCopy,message};if(saved.afterCopy==='\u4e0d\u63d0\u793a'){$('#toast').style.display='none';return;}toast(saved.afterCopy==='\u7cfb\u7edf\u901a\u77e5'?'\u7cfb\u7edf\u901a\u77e5\uff08\u6a21\u62df\uff09':message);}
function completeCapture(kind,skipAuto=false){if(state.textPoint||captureGesturePending())return;if(kind===undefined){if(saved.finish==='\u590d\u5236\u5e76\u8d34\u5230\u684c\u9762')kind='pin';else if(saved.finish==='\u4fdd\u5b58\u5230\u6587\u4ef6\uff08\u6bcf\u6b21\u8be2\u95ee\uff09'){openModal('save');return;}else kind='copy';}if(saved.autoSave&&!skipAuto)simulateAutoCopy();if(!state.editingPin&&!state.localImage&&!state.guideCapture&&saved.rememberRegion&&state.selection)state.lastRegion={region:clone(state.selection),layout:prototypeCaptureLayout()};const completedMarks=clone(state.marks),completedUndo=clone(state.undoSteps),completedRedo=clone(state.redo);state.selection=null;resetEdits();if(state.guideCapture){state.guideCapture=false;navigate('onboarding/done',true);completionFeedback('演练完成：标注直接在截图浮层完成。');return;}if(state.editingPin){state.editingPin=false;state.pinHidden=false;if(kind==='pin'){state.pinMarks=completedMarks;state.pinUndoSteps=completedUndo;state.pinRedo=completedRedo;}navigate('pins',true);completionFeedback(kind==='pin'?'已应用到原贴图，保留位置、旋转和外观（模拟）。':'已输出本次编辑；原贴图保持不变（模拟）。');return;}if(kind==='pin'){addPin(completedMarks,completedUndo,completedRedo);state.pinHidden=false;navigate('pins',true);if(saved.pinPassThrough)openModal('pass-confirm');completionFeedback('已退出截图浮层，图片留在桌面（模拟）。');}else{navigate('idle',true);completionFeedback(kind==='save'?'保存成功，已回到桌面（模拟，未写入文件）。':'已复制并退出浮层（模拟，未写入系统剪贴板）。');}}
function commitText(){const input=$('#annotation-text');if(input?.value.trim()&&state.textPoint){const m={tool:'text',a:clone(state.textPoint),b:clone(state.textPoint),color:state.color,stroke:state.textTarget!==null?state.marks[state.textTarget].stroke:state.stroke,text:input.value.trim(),textSize:state.textSize||saved.textSize,textFont:state.textFont||saved.textFont};if(state.textTarget===null){checkpoint();state.marks.push(m);}else if(JSON.stringify(state.marks[state.textTarget])!==JSON.stringify(m)){checkpoint();state.marks[state.textTarget]=m;}}state.textPoint=null;state.textTarget=null;render();}
